import{_ as l,o as r,c as t,ag as s}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Tunnels","description":"","frontmatter":{},"headers":[],"relativePath":"fr/car-wash/tunnels.md","filePath":"fr/car-wash/tunnels.md"}'),a={name:"fr/car-wash/tunnels.md"};function n(o,e,i,u,c,d){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="tunnels" tabindex="-1">Tunnels <a class="header-anchor" href="#tunnels" aria-label="Permalink to &quot;Tunnels&quot;">​</a></h1><p>Un tunnel, c&#39;est une entrée où le conducteur s&#39;arrête, une ligne que suit le véhicule, et les arches, brosses et séchoir placés le long. Deux tunnels sont prêts à l&#39;emploi : <strong>Strawberry</strong> et <strong>Little Seoul</strong>.</p><h2 id="deroulement-d-un-lavage" tabindex="-1">Déroulement d&#39;un lavage <a class="header-anchor" href="#deroulement-d-un-lavage" aria-label="Permalink to &quot;Déroulement d&#39;un lavage&quot;">​</a></h2><ol><li>Le conducteur s&#39;arrête à l&#39;entrée, face à la sortie. Une invite affiche le prix le plus bas.</li><li><strong>E</strong> ouvre le menu de lavage avec les formules et leurs prix (remises par métier et pourcentage du tunnel compris).</li><li>Le prix est payé, puis le véhicule est guidé le long de la ligne : savon, brosses, rinçage, séchoir, selon la formule. Tout le monde autour voit le même lavage.</li><li>À la sortie, le véhicule est propre, et ciré si la formule comprend de la cire.</li></ol><p>L&#39;entrée refuse le lavage quand :</p><ul><li>le tunnel est déjà utilisé (un véhicule à la fois) ;</li><li>le véhicule est dans le mauvais sens ;</li><li>un autre véhicule bloque la voie ;</li><li>la classe du véhicule est refusée, ou le véhicule est trop large (<code>BlockedClasses</code>, <code>MaxVehicleWidth</code>) ;</li><li>le véhicule est déjà propre et <code>RequireDirt</code> est activé ;</li><li>le joueur ne peut pas payer.</li></ul><h2 id="l-editeur-de-tunnels" tabindex="-1">L&#39;éditeur de tunnels <a class="header-anchor" href="#l-editeur-de-tunnels" aria-label="Permalink to &quot;L&#39;éditeur de tunnels&quot;">​</a></h2><p>Ouvrez-le avec <code>/nay:carwash</code>, ou avec <strong>Gérer les tunnels</strong> sur la page Car Wash de <code>/nay</code>. Il demande le scope <code>nay_car_wash.config</code>.</p><p>Le gestionnaire liste les tunnels : y aller, le modifier, l&#39;ouvrir ou le fermer, le supprimer. Pour en ajouter un :</p><ol><li><p><strong>Créer ici</strong> : placez-vous à l&#39;entrée, face à la sortie. Ou <strong>Copier</strong> une des stations du jeu de base.</p></li><li><p>Choisissez un élément (entrée, début et fin de ligne, arches, brosses, séchoir) et déplacez-le avec les boutons ou le clavier :</p><ul><li>flèches : avancer, reculer, gauche, droite le long de la voie ;</li><li>Page Up / Page Down : hauteur ;</li><li>Q / E : rotation ;</li><li>Tab : élément suivant.</li></ul><p>Trois tailles de pas permettent les réglages fins.</p></li><li><p><strong>À ma position</strong> et <strong>Au sol</strong> recalent l&#39;élément choisi. <strong>Se déplacer</strong> (G) libère la souris pour bouger et regarder. Appuyez de nouveau sur G pour retrouver le panneau.</p></li><li><p><strong>Enregistrer le tunnel</strong>. Le tunnel est actif pour tous les joueurs tout de suite.</p></li></ol><p>L&#39;éditeur remplit le réglage <code>Tunnels</code>. Ses champs sont décrits sur la page <a href="/fr/car-wash/settings#tunnels">Réglages</a>.</p>',11)])])}const h=l(a,[["render",n]]);export{g as __pageData,h as default};
